// The "Upcoming Islamic events" section of /calendar/ as one HTML string (K07c). The build writes it into the first
// HTML and the React page renders the same string in the visitor's language, so a crawler and a visitor read the same words.
// Colours come from --ie-* variables (the page sets them from the sky's page tokens; the fallbacks are the Day page).
import { upcoming, daysUntil } from './islamicEvents.mjs';

export const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const RTL = new Set(['ar', 'ur']);
const LANGS_WITH_PAGES = new Set(['en', 'ar', 'ur', 'id', 'ms']); // /<lang>/islamic-calendar/ event pages exist in these
const bdi = (s) => `<bdi>${esc(s)}</bdi>`;

// Nur-style icons: one line drawing, one gold point of light, no figures (as on the home page).
const G = '<circle class="ie-gold" ';
const ln = (d) => `<path d="${d}" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>`;
export const ICONS = {
  newYear: `${ln('M5 6.5h14V19H5zM5 10.5h14M9 4.5v3M15 4.5v3')}${G}cx="12" cy="14.8" r="1.5"/>`,
  ashura: `${ln('M7 4.5h8.5L18 7v12.5H7zM10 10h5M10 13h5')}${G}cx="18.2" cy="4.6" r="1.4"/>`,
  mawlid: `${ln('M5 20v-7a7 7 0 0 1 14 0v7M3.5 20h17')}${G}cx="12" cy="6" r="1.4"/>`,
  miraj: `${ln('M4 17c3-1 5-4.5 8-4.5S17 16 20 15.5M6 9l2 1.5M16 6.5l1.8 1')}${G}cx="12" cy="6.4" r="1.4"/>`,
  baraat: `${ln('M12 3.5v3M12 17.5v3M3.5 12h3M17.5 12h3M6.2 6.2l2 2M15.8 15.8l2 2M17.8 6.2l-2 2M8.2 15.8l-2 2')}${G}cx="12" cy="12" r="1.7"/>`,
  ramadan: `${ln('M15 4.2a8 8 0 1 0 4.8 12.6A6.6 6.6 0 1 1 15 4.2z')}${G}cx="18.2" cy="7" r="1.4"/>`,
  nuzul: `${ln('M12 7C10 5.5 7 5 4 5.5v13c3-.5 6 0 8 1.5 2-1.5 5-2 8-1.5v-13C17 5 14 5.5 12 7zM12 7v13')}${G}cx="12" cy="3.4" r="1.4"/>`,
  qadr: `${ln('M12 3c-4.5 3-6 6.5-6 9.8a6 6 0 0 0 12 0C18 9.5 16.5 6 12 3z')}${G}cx="12" cy="13" r="1.5"/>`,
  eidFitr: `${ln('M7 17a5 5 0 0 1 10 0M5 17h14M9 20.5h6M12 11.5V9')}${G}cx="12" cy="6.6" r="1.4"/>`,
  hajj: `${ln('M5.5 8.5h13V20h-13zM5.5 12h13M10 20v-4.5h4V20')}${G}cx="12" cy="5" r="1.4"/>`,
  arafah: `${ln('M3 19.5l6-9 3.5 5 2.5-3 6 7zM3 19.5h18')}${G}cx="17.5" cy="6" r="1.4"/>`,
  eidAdha: `${ln('M12 4a8 8 0 1 0 0 16 8 8 0 0 0 0-16zM8.5 14.5c1.2 1.4 5.8 1.4 7 0')}${G}cx="12" cy="9.6" r="1.4"/>`,
};

export const EVENTS_CSS = `.ie{margin-block:48px;color:var(--ie-ink,#15241C)}.ie *{box-sizing:border-box}.ie h2{font:400 clamp(26px,3.4vw,36px)/1.15 var(--ie-serif,Georgia,serif);margin:0 0 8px}
.ie-lead{margin:0 0 24px;color:var(--ie-soft,#4F564E);max-inline-size:62ch;line-height:1.55}.ie-grid{list-style:none;margin:0;padding:0;display:grid;gap:16px;grid-template-columns:repeat(auto-fill,minmax(min(100%,272px),1fr))}
.ie-card{padding:22px;border-radius:22px;background:var(--ie-card,#FFFDF8);box-shadow:inset 0 0 0 1px var(--ie-line,#E4DCC8);display:flex;flex-direction:column;gap:8px;block-size:100%}
.ie-top{display:flex;align-items:center;gap:12px}.ie-ico{inline-size:40px;block-size:40px;flex:none;color:var(--ie-accent,#0E5C40)}.ie-gold{fill:var(--ie-gold,#8A6420)}
.ie-card h3{margin:0;font:400 20px/1.2 var(--ie-serif,Georgia,serif)}.ie-card p{margin:0;line-height:1.5}.ie-soft{color:var(--ie-soft,#4F564E);font-size:15px}
.ie-count{font-size:13px;font-weight:600;letter-spacing:.06em;color:var(--ie-gold,#8A6420);text-transform:uppercase}.ie-dates{display:grid;gap:2px;font-size:15px}
.ie-dates span{color:var(--ie-soft,#4F564E);font-size:12px;letter-spacing:.1em;text-transform:uppercase;margin-inline-end:6px}
.ie-card a{color:var(--ie-accent,#0E5C40);font-weight:600;text-decoration:none;display:inline-flex;align-items:center;min-block-size:48px}.ie-card a:hover,.ie-foot a:hover{text-decoration:underline;text-underline-offset:3px}
.ie-card a.ie-stretch{margin-block-start:auto}.ie-foot{margin-block-start:20px;display:flex;flex-wrap:wrap;gap:8px 24px;align-items:center}.ie-foot a{color:var(--ie-accent,#0E5C40);font-weight:600;display:inline-flex;align-items:center;min-block-size:48px}
.ie-note{margin:0;color:var(--ie-soft,#4F564E);font-size:14px}`;

/** Plural form key for a day count in a language (ar has six forms; the rest use one/other). */
const form = (days, n, lang) => { const k = new Intl.PluralRules(lang).select(n); return days[k] || days.other; };

/**
 * @param {object} o
 * @param {string} o.today YYYY-MM-DD, the visitor's date (the build's UTC date in the pre-render)
 * @param {string} o.lang one of en ar ur fr es id ms tr
 * @param {object} o.s the "events" block of locales/<lang>/calendar.json
 * @returns {{html:string, items:object[]}}
 */
export function eventsSection({ today, lang = 'en', s }) {
  const items = upcoming(today);
  const nf = new Intl.NumberFormat(s.locale, { useGrouping: false });
  const g = (d) => new Date(`${d}T12:00:00Z`).toLocaleDateString(s.locale, { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });
  const h = (x) => `${nf.format(x.d)} ${s.months[x.m - 1]} ${nf.format(x.y)} ${s.ah}`;
  const pre = lang === 'en' ? '' : `/${lang}`;
  const card = (o) => {
    const name = s.names[o.ev.slug];
    const when = o.days === 0 ? s.today : o.days === 1 ? s.tomorrow : form(s.days, o.days, lang).replace('{{n}}', nf.format(o.days));
    const gd = o.end ? s.range.replace('{{a}}', g(o.date)).replace('{{b}}', g(o.end)) : g(o.date);
    const y = o.date.slice(0, 4);
    const link = o.ev.noPage || o.ev.slug === 'ramadan' ? { href: '/ramadan/', text: s.ramadanPage } : { href: `${LANGS_WITH_PAGES.has(lang) ? pre : ''}/islamic-calendar/${o.ev.slug}-${y}/`, text: s.open };
    return `<li class="ie-card" data-event="${o.ev.slug}" data-date="${o.date}"><div class="ie-top"><svg class="ie-ico" viewBox="0 0 24 24" aria-hidden="true" focusable="false">${ICONS[o.ev.icon]}</svg><h3>${esc(name)}</h3></div>`
      + `<p class="ie-count">${bdi(when)}</p><div class="ie-dates"><p><span>${esc(s.hLabel)}</span>${bdi(h(o.hijri))}</p><p><span>${esc(s.gLabel)}</span><time datetime="${o.date}">${bdi(gd)}</time></p></div>`
      + `<p class="ie-soft">${esc(s.about[o.ev.slug])}${o.ev.night ? ` ${esc(s.nightPre)}` : ''}</p><a class="ie-stretch" href="${link.href}">${esc(link.text)}</a></li>`;
  };
  const html = `<section class="ie" id="islamic-events" aria-labelledby="ie-h" lang="${lang}" dir="${RTL.has(lang) ? 'rtl' : 'ltr'}"><style>${EVENTS_CSS}</style><h2 id="ie-h">${esc(s.title)}</h2><p class="ie-lead">${esc(s.lead)}</p>`
    + `<ul class="ie-grid">${items.map(card).join('')}</ul><div class="ie-foot"><a href="${LANGS_WITH_PAGES.has(lang) ? pre : ''}/islamic-calendar/">${esc(s.all)}</a><p class="ie-note">${esc(s.note)}</p></div></section>`;
  return { html, items };
}

/** Event JSON-LD for the section: an ItemList of Event nodes, each with its own @id (nothing refers to an @id that is not defined). */
export function eventsLd({ today, s, url }) {
  const items = upcoming(today);
  const itemList = { '@type': 'ItemList', '@id': `${url}#islamic-events`, name: s.title, numberOfItems: items.length,
    itemListElement: items.map((o, i) => ({ '@type': 'ListItem', position: i + 1, item: {
      '@type': 'Event', '@id': `${url}#event-${o.ev.slug}`, name: `${s.names[o.ev.slug]}`, startDate: o.date, endDate: o.end || o.date,
      eventStatus: 'https://schema.org/EventScheduled', eventAttendanceMode: 'https://schema.org/OfflineEventAttendanceMode',
      location: { '@type': 'Place', name: 'Worldwide', address: 'Worldwide' }, description: s.about[o.ev.slug],
      url: o.ev.noPage || o.ev.slug === 'ramadan' ? 'https://imuslimlife.com/ramadan/' : `https://imuslimlife.com/islamic-calendar/${o.ev.slug}-${o.date.slice(0, 4)}/` } })) };
  return itemList;
}
export { daysUntil };
