// The upcoming Islamic events for the Calendar page (K07c). Pure: no I/O, no clock of its own (the caller passes
// today as YYYY-MM-DD), so the build-time pre-render and the React page share it and tests can pin the date.
// Dates are the calculated Umm al-Qura calendar from Intl, the same source and the same event list as the
// /islamic-calendar/ pages (scripts/city-pages/calendar.mjs); worker/test/calendar-events.test.js compares the two.
export const EVENTS = [
  { slug: 'islamic-new-year', hm: 1, hd: 1, icon: 'newYear' },
  { slug: 'ashura', hm: 1, hd: 10, icon: 'ashura' },
  { slug: 'mawlid', hm: 3, hd: 12, icon: 'mawlid' },
  { slug: 'isra-miraj', hm: 7, hd: 27, night: true, icon: 'miraj' },
  { slug: 'mid-shaban', hm: 8, hd: 15, night: true, icon: 'baraat' },
  { slug: 'ramadan', hm: 9, hd: 1, icon: 'ramadan' },
  // Nuzul al-Quran, 17 Ramadan (the old home's list had it; /islamic-calendar/ has no page for it, so its card links to /ramadan/).
  { slug: 'nuzul-al-quran', hm: 9, hd: 17, icon: 'nuzul', noPage: true },
  { slug: 'laylat-al-qadr', hm: 9, hd: 27, night: true, icon: 'qadr' },
  { slug: 'eid-al-fitr', hm: 10, hd: 1, icon: 'eidFitr' },
  { slug: 'dhul-hijjah', hm: 12, hd: 1, days: 10, icon: 'hajj' },
  { slug: 'day-of-arafah', hm: 12, hd: 9, icon: 'arafah' },
  { slug: 'eid-al-adha', hm: 12, hd: 10, icon: 'eidAdha' },
];

const DAY = 864e5;
const umq = new Intl.DateTimeFormat('en-u-ca-islamic-umalqura', { day: 'numeric', month: 'numeric', year: 'numeric', timeZone: 'UTC' });
export const isoOf = (ms) => new Date(ms).toISOString().slice(0, 10);
export const addDays = (date, n) => isoOf(Date.parse(`${date}T12:00:00Z`) + n * DAY);
export function hijriOf(date) {
  const p = Object.fromEntries(umq.formatToParts(new Date(`${date}T12:00:00Z`)).map((x) => [x.type, x.value]));
  return { d: +p.day, m: +p.month, y: +String(p.year).split(' ')[0] };
}
export const daysUntil = (from, to) => Math.round((Date.parse(`${to}T12:00:00Z`) - Date.parse(`${from}T12:00:00Z`)) / DAY);

/** Every event occurrence from `from` for `count` days, in date order: [{ ev, date, end, hijri }]. */
export function occurrences(from, count) {
  const out = [];
  for (let i = 0; i < count; i++) {
    const date = addDays(from, i);
    const h = hijriOf(date);
    for (const ev of EVENTS) if (h.m === ev.hm && h.d === ev.hd) out.push({ ev, date, end: ev.days ? addDays(date, ev.days - 1) : null, hijri: h });
  }
  return out;
}

/** The next occurrence of each event, today included, soonest first, with days until. */
export function upcoming(today) {
  const seen = new Set();
  return occurrences(today, 366).filter((o) => !seen.has(o.ev.slug) && seen.add(o.ev.slug)).map((o) => ({ ...o, days: daysUntil(today, o.date) }));
}
