import React, { useMemo } from 'react';
import { Box, useTheme } from '@mui/material';
import { useTranslation } from 'react-i18next';
import { eventsSection } from '../utils/islamicEventsView.mjs';

// "Upcoming Islamic events" on /calendar/ (K07c). The same string the build wrote into the first HTML, in the visitor's language,
// with the visitor's own date; colours follow the page theme (the sky's page tokens on dressed pages).
const localIso = (d = new Date()) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

export default function IslamicEventsSection() {
    const { t, i18n } = useTranslation('calendar');
    const theme = useTheme();
    const lang = i18n.resolvedLanguage || 'en';
    const s = t('events', { returnObjects: true });
    const html = useMemo(() => (s && s.names ? eventsSection({ today: localIso(), lang, s }).html : ''), [s, lang]);
    const p = theme.palette;
    if (!html) return null;
    return (
        <Box
            sx={{ '--ie-ink': p.text.primary, '--ie-soft': p.text.secondary, '--ie-card': p.background.paper, '--ie-line': p.divider, '--ie-gold': p.secondary.main, '--ie-accent': p.primary.main, '--ie-serif': theme.typography.h1.fontFamily }}
            dangerouslySetInnerHTML={{ __html: html }}
        />
    );
}
